test_suite:
test('uses controlled value when provided', () => {
  const [value] = renderHook(() =>
    useControlled({ controlled: 'external', default: 'internal' })
  ).result.current;
  expect(value).toBe('external');
});

test('uses default when controlled is undefined', () => {
  const [value] = renderHook(() =>
    useControlled({ controlled: undefined, default: 'fallback' })
  ).result.current;
  expect(value).toBe('fallback');
});

test('uncontrolled setter updates internal state', () => {
  const { result } = renderHook(() =>
    useControlled({ controlled: undefined, default: 0 })
  );
  act(() => result.current[1](99));
  expect(result.current[0]).toBe(99);
});

test('controlled value updates when prop changes', () => {
  const { result, rerender } = renderHook(
    ({ v }) => useControlled({ controlled: v, default: 'x' }),
    { initialProps: { v: 'a' as string } }
  );
  rerender({ v: 'b' });
  expect(result.current[0]).toBe('b');
});

// __hidden__
test('setter is a function', () => {
  const [, setter] = renderHook(() =>
    useControlled({ controlled: undefined, default: '' })
  ).result.current;
  expect(typeof setter).toBe('function');
});

solution:
import { useState, useCallback } from 'react';

export function useControlled<T>({
  controlled,
  default: defaultValue,
}: {
  controlled?: T;
  default: T;
}): [T, (v: T) => void] {
  const isControlled = controlled !== undefined;
  const [internalValue, setInternalValue] = useState<T>(defaultValue);

  const setValue = useCallback((v: T) => {
    if (!isControlled) setInternalValue(v);
  }, [isControlled]);

  return [isControlled ? controlled : internalValue, setValue];
}
